"""
checkability.py — score and report Halcyon Threshold checkability assessments.

Standard library only. Python 3.9+.

Usage:
    python tools/checkability.py validate [--dir data/assessments]
    python tools/checkability.py report   [--dir data/assessments] [--out report.md]
    python tools/checkability.py agreement [--dir data/assessments]
    python tools/checkability.py selftest

Design notes:
  * An item score with no supporting evidence note is rejected. This is deliberate: the rubric is
    only as good as the evidence trail, and it is easy to drift into scoring from memory.
  * "NA" is permitted only on items where the rubric allows it, and NA items are dropped from both
    the numerator and the denominator so that scores stay comparable.
  * Nothing here decides anything. It arithmetic-checks human judgement and makes disagreement
    visible.
"""

from __future__ import annotations

import argparse
import json
import pathlib
import sys
from collections import defaultdict
from typing import Any, Dict, List, Optional, Tuple

RUBRIC_VERSION = "0.1"
MIN_NOTE_CHARS = 15

# key, human label, is "NA" an allowed score?
ITEMS: List[Tuple[str, str, bool]] = [
    ("claim_specificity", "Claim specificity", False),
    ("model_identification", "Model identification", False),
    ("artifact_availability", "Artifact availability", False),
    ("data_and_contamination", "Data availability and contamination", False),
    ("scaffold_disclosure", "Scaffold and tool disclosure", True),
    ("grader_disclosure", "Grader disclosure", True),
    ("determinism_variance", "Determinism and variance", False),
    ("replication_cost", "Replication cost", False),
    ("negative_results", "Negative results and ablations", False),
    ("prior_checking", "Prior independent checking", False),
]

ITEM_KEYS = [k for k, _, _ in ITEMS]
ITEM_LABELS = {k: label for k, label, _ in ITEMS}
NA_ALLOWED = {k: na for k, _, na in ITEMS}

VALID_SCORES = {0, 1, 2}


class ValidationError(Exception):
    pass


# ----------------------------------------------------------------------------- loading


def load_dir(directory: pathlib.Path) -> List[Dict[str, Any]]:
    """Load every *.json assessment in a directory, skipping templates."""
    records = []
    for path in sorted(directory.glob("*.json")):
        if path.name.startswith("_") or "TEMPLATE" in path.name.upper():
            continue
        with path.open("r", encoding="utf-8") as fh:
            try:
                data = json.load(fh)
            except json.JSONDecodeError as exc:
                raise ValidationError(f"{path.name}: not valid JSON — {exc}") from exc
        data["_file"] = path.name
        records.append(data)
    return records


# -------------------------------------------------------------------------- validation


def validate(record: Dict[str, Any]) -> List[str]:
    """Return a list of problems. Empty list means the record is usable."""
    problems: List[str] = []
    where = record.get("_file", "<record>")

    for field in ("paper", "coder", "coded_on", "rubric_version", "items"):
        if field not in record:
            problems.append(f"{where}: missing top-level field '{field}'")

    paper = record.get("paper", {})
    if not isinstance(paper, dict):
        problems.append(f"{where}: 'paper' must be an object")
    else:
        for field in ("id", "title"):
            if not paper.get(field):
                problems.append(f"{where}: paper.{field} is missing or empty")

    if record.get("rubric_version") != RUBRIC_VERSION:
        problems.append(
            f"{where}: rubric_version {record.get('rubric_version')!r} "
            f"does not match tool version {RUBRIC_VERSION!r}"
        )

    items = record.get("items", {})
    if not isinstance(items, dict):
        problems.append(f"{where}: 'items' must be an object")
        return problems

    for key in ITEM_KEYS:
        if key not in items:
            problems.append(f"{where}: missing rubric item '{key}'")
            continue
        entry = items[key]
        if not isinstance(entry, dict):
            problems.append(f"{where}: item '{key}' must be an object with score and note")
            continue

        score = entry.get("score")
        if score == "NA":
            if not NA_ALLOWED[key]:
                problems.append(f"{where}: item '{key}' may not be scored NA")
        elif score not in VALID_SCORES:
            problems.append(f"{where}: item '{key}' has invalid score {score!r} (expected 0, 1, 2 or 'NA')")

        note = (entry.get("note") or "").strip()
        if len(note) < MIN_NOTE_CHARS:
            problems.append(
                f"{where}: item '{key}' needs an evidence note of at least "
                f"{MIN_NOTE_CHARS} characters (got {len(note)})"
            )

    for key in items:
        if key not in ITEM_KEYS:
            problems.append(f"{where}: unknown rubric item '{key}'")

    return problems


# ------------------------------------------------------------------------------ scoring


def score_record(record: Dict[str, Any]) -> Dict[str, Any]:
    items = record.get("items", {})
    earned = 0
    possible = 0
    na_items: List[str] = []

    for key in ITEM_KEYS:
        score = items.get(key, {}).get("score")
        if score == "NA":
            na_items.append(key)
            continue
        if score in VALID_SCORES:
            earned += score
            possible += 2

    pct = (100.0 * earned / possible) if possible else 0.0
    return {
        "paper_id": record.get("paper", {}).get("id", "?"),
        "title": record.get("paper", {}).get("title", "?"),
        "coder": record.get("coder", "?"),
        "earned": earned,
        "possible": possible,
        "pct": pct,
        "na_items": na_items,
    }


